.darma-loader-darma-b13-repeat-loop { --accent: var(--loader-color, #6366f1); --accent-2: var(--loader-secondary-color, #22d3ee); width: var(--loader-size, 88px); height: var(--loader-size, 88px); position: relative; animation: darma-loader-darma-b13-repeat-loop-cycle calc(var(--loader-speed, 1s) * 1.9) cubic-bezier(.6, 0, .3, 1) infinite; }
.darma-loader-darma-b13-repeat-loop span { position: absolute; inset: 0; border-radius: 50%; border: calc(var(--loader-size, 88px) * .1) solid transparent; }
.darma-loader-darma-b13-repeat-loop span:nth-child(1) { border-top-color: var(--accent); border-right-color: var(--accent); }
.darma-loader-darma-b13-repeat-loop span:nth-child(2) { border-bottom-color: var(--accent-2); border-left-color: var(--accent-2); }
.darma-loader-darma-b13-repeat-loop span::after { content: ''; position: absolute; width: 46%; height: 30%; }
.darma-loader-darma-b13-repeat-loop span:nth-child(1)::after { top: 34%; right: -30%; clip-path: polygon(0 0, 100% 0, 50% 100%); background: var(--accent); }
.darma-loader-darma-b13-repeat-loop span:nth-child(2)::after { bottom: 34%; left: -30%; clip-path: polygon(50% 0, 100% 100%, 0 100%); background: var(--accent-2); }
@keyframes darma-loader-darma-b13-repeat-loop-cycle { 0% { transform: rotate(0deg); } 44% { transform: rotate(196deg); } 56% { transform: rotate(196deg); } 100% { transform: rotate(360deg); } }

